import 'dart:io';import 'dart:typed_data';import 'dart:convert';import 'package:hive_flutter/hive_flutter.dart';import 'package:path_provider/path_provider.dart';import 'package:encrypt/encrypt.dart' as encrypt;import 'package:mime/mime.dart';class VaultFile {  final String id;  final String name;  final String path;  final String folderId;  final FileType type;  final int size;  final DateTime createdAt;  final DateTime modifiedAt;  final List<String> tags;  final bool isEncrypted;  final String? checksum;  final int version;  final String ownerId;  VaultFile({    required this.id,    required this.name,    required this.path,    required this.folderId,    required this.type,    required this.size,    required this.createdAt,    required this.modifiedAt,    this.tags = const [],    this.isEncrypted = true,    this.checksum,    this.version = 1,    required this.ownerId,  });  Map<String, dynamic> toJson() => {        'id': id,        'name': name,        'path': path,        'folderId': folderId,        'type': type.index,        'size': size,        'createdAt': createdAt.toIso8601String(),        'modifiedAt': modifiedAt.toIso8601String(),        'tags': tags,        'isEncrypted': isEncrypted,        'checksum': checksum,        'version': version,        'ownerId': ownerId,      };  factory VaultFile.fromJson(Map<String, dynamic> json) => VaultFile(        id: json['id'],        name: json['name'],        path: json['path'],        folderId: json['folderId'],        type: FileType.values[json['type']],        size: json['size'],        createdAt: DateTime.parse(json['createdAt']),        modifiedAt: DateTime.parse(json['modifiedAt']),        tags: List<String>.from(json['tags'] ?? []),        isEncrypted: json['isEncrypted'] ?? true,        checksum: json['checksum'],        version: json['version'] ?? 1,        ownerId: json['ownerId'],      );  VaultFile copyWith({    String? id,    String? name,    String? path,    String? folderId,    FileType? type,    int? size,    DateTime? createdAt,    DateTime? modifiedAt,    List<String>? tags,    bool? isEncrypted,    String? checksum,    int? version,    String? ownerId,  }) =>      VaultFile(        id: id ?? this.id,        name: name ?? this.name,        path: path ?? this.path,        folderId: folderId ?? this.folderId,        type: type ?? this.type,        size: size ?? this.size,        createdAt: createdAt ?? this.createdAt,        modifiedAt: modifiedAt ?? this.modifiedAt,        tags: tags ?? this.tags,        isEncrypted: isEncrypted ?? this.isEncrypted,        checksum: checksum ?? this.checksum,        version: version ?? this.version,        ownerId: ownerId ?? this.ownerId,      );}enum FileType {  folder,  image,  video,  audio,  document,  pdf,  spreadsheet,  archive,  other}class VaultFolder {  final String id;  final String name;  final String? parentId;  final DateTime createdAt;  final List<String> sharedWithDeviceIds;  final bool isShared;  final String ownerId;  VaultFolder({    required this.id,    required this.name,    this.parentId,    required this.createdAt,    this.sharedWithDeviceIds = const [],    this.isShared = false,    required this.ownerId,  });  Map<String, dynamic> toJson() => {        'id': id,        'name': name,        'parentId': parentId,        'createdAt': createdAt.toIso8601String(),        'sharedWithDeviceIds': sharedWithDeviceIds,        'isShared': isShared,        'ownerId': ownerId,      };  factory VaultFolder.fromJson(Map<String, dynamic> json) => VaultFolder(        id: json['id'],        name: json['name'],        parentId: json['parentId'],        createdAt: DateTime.parse(json['createdAt']),        sharedWithDeviceIds:            List<String>.from(json['sharedWithDeviceIds'] ?? []),        isShared: json['isShared'] ?? false,        ownerId: json['ownerId'],      );}class FileVersion {  final String id;  final String fileId;  final String path;  final int versionNumber;  final DateTime createdAt;  final String checksum;  FileVersion({    required this.id,    required this.fileId,    required this.path,    required this.versionNumber,    required this.createdAt,    required this.checksum,  });  Map<String, dynamic> toJson() => {        'id': id,        'fileId': fileId,        'path': path,        'versionNumber': versionNumber,        'createdAt': createdAt.toIso8601String(),        'checksum': checksum,      };  factory FileVersion.fromJson(Map<String, dynamic> json) => FileVersion(        id: json['id'],        fileId: json['fileId'],        path: json['path'],        versionNumber: json['versionNumber'],        createdAt: DateTime.parse(json['createdAt']),        checksum: json['checksum'],      );}class FileTransfer {  final String id;  final String fileId;  final String senderId;  final String receiverId;  final int totalChunks;  final int completedChunks;  final TransferStatus status;  final bool isOutgoing;  FileTransfer({    required this.id,    required this.fileId,    required this.senderId,    required this.receiverId,    required this.totalChunks,    this.completedChunks = 0,    this.status = TransferStatus.pending,    this.isOutgoing = false,  });  double get progress => totalChunks > 0 ? completedChunks / totalChunks : 0;}enum TransferStatus { pending, transferring, completed, failed, paused }class FileVaultService {  static const String _filesBoxName = 'vault_files';  static const String _foldersBoxName = 'vault_folders';  static const String _versionsBoxName = 'vault_versions';  static const String _transfersBoxName = 'vault_transfers';  static const String _tagsBoxName = 'vault_tags';  static const String _binBoxName = 'vault_bin';  Box<String>? _filesBox;  Box<String>? _foldersBox;  Box<String>? _versionsBox;  Box<String>? _transfersBox;  Box<String>? _tagsBox;  Box<String>? _binBox;  late Directory _vaultDir;  late Directory _versionsDir;  String? _encryptionKey;  static FileVaultService? _instance;  static Future<FileVaultService> getInstance() async {    if (_instance == null) {      _instance = FileVaultService._internal();      await _instance!._initialize();    }    return _instance!;  }  FileVaultService._internal();  Future<void> _initialize() async {    _filesBox = await Hive.openBox(_filesBoxName);    _foldersBox = await Hive.openBox(_foldersBoxName);    _versionsBox = await Hive.openBox(_versionsBoxName);    _transfersBox = await Hive.openBox(_transfersBoxName);    _tagsBox = await Hive.openBox(_tagsBoxName);    _binBox = await Hive.openBox(_binBoxName);    final appDir = await getApplicationDocumentsDirectory();    _vaultDir = Directory('${appDir.path}/vault');    _versionsDir = Directory('${appDir.path}/vault_versions');    await _vaultDir.create(recursive: true);    await _versionsDir.create(recursive: true);    _generateEncryptionKey();  }  void _generateEncryptionKey() {    final key = encrypt.Key.fromSecureRandom(32);    _encryptionKey = key.base64;  }  FileType _getFileType(String filePath) {    final mime = lookupMimeType(filePath) ?? '';    if (mime.startsWith('image/')) return FileType.image;    if (mime.startsWith('video/')) return FileType.video;    if (mime.startsWith('audio/')) return FileType.audio;    if (mime.contains('pdf')) return FileType.pdf;    if (mime.contains('spreadsheet') || mime.contains('excel'))      return FileType.spreadsheet;    if (mime.contains('document') || mime.contains('word'))      return FileType.document;    if (mime.contains('zip') || mime.contains('tar') || mime.contains('rar'))      return FileType.archive;    if (mime.startsWith('text/')) return FileType.document;    return FileType.other;  }  String _computeChecksum(List<int> bytes) {    int hash = 0;    for (var byte in bytes) {      hash = ((hash << 5) - hash + byte) & 0xFFFFFFFF;    }    return hash.toRadixString(16);  }  Future<VaultFile> saveFile({    required String sourcePath,    required String folderId,    required String ownerId,    List<String>? tags,    bool encrypt = true,  }) async {    final sourceFile = File(sourcePath);    if (!await sourceFile.exists()) {      throw Exception('Source file does not exist');    }    final id = 'file_${DateTime.now().millisecondsSinceEpoch}';    final fileName = sourcePath.split('/').last;    final destPath = '${_vaultDir.path}/$id';    var bytes = await sourceFile.readAsBytes();    var checksum = _computeChecksum(bytes);    if (encrypt && _encryptionKey != null) {      bytes = _encryptData(bytes);    }    final destFile = File(destPath);    await destFile.writeAsBytes(bytes);    final stat = await sourceFile.stat();    final vaultFile = VaultFile(      id: id,      name: fileName,      path: destPath,      folderId: folderId,      type: _getFileType(fileName),      size: bytes.length,      createdAt: DateTime.now(),      modifiedAt: stat.modified,      tags: tags ?? [],      isEncrypted: encrypt,      checksum: checksum,      ownerId: ownerId,    );    await _filesBox?.put(id, jsonEncode(vaultFile.toJson()));    return vaultFile;  }  Uint8List _encryptData(Uint8List data) {    if (_encryptionKey == null) return data;    final key = encrypt.Key.fromBase64(_encryptionKey!);    final iv = encrypt.IV.fromSecureRandom(16);    final encrypter =        encrypt.Encrypter(encrypt.AES(key, mode: encrypt.AESMode.cbc));    final encrypted = encrypter.encryptBytes(data, iv: iv);    final result = Uint8List(16 + encrypted.bytes.length);    result.setRange(0, 16, iv.bytes);    result.setRange(16, result.length, encrypted.bytes);    return result;  }  Uint8List _decryptData(Uint8List data) {    if (_encryptionKey == null) return data;    if (data.length < 16) return data;    try {      final iv = encrypt.IV(data.sublist(0, 16));      final encrypted = encrypt.Encrypted(data.sublist(16));      final key = encrypt.Key.fromBase64(_encryptionKey!);      final encrypter =          encrypt.Encrypter(encrypt.AES(key, mode: encrypt.AESMode.cbc));      return Uint8List.fromList(encrypter.decryptBytes(encrypted, iv: iv));    } catch (e) {      return data;    }  }  Future<Uint8List?> loadFile(String fileId) async {    final json = _filesBox?.get(fileId);    if (json == null) return null;    final file = VaultFile.fromJson(jsonDecode(json));    final localFile = File(file.path);    if (!await localFile.exists()) return null;    var bytes = await localFile.readAsBytes();    if (file.isEncrypted) {      bytes = _decryptData(bytes);    }    return bytes;  }  Future<VaultFolder> createFolder({    required String name,    String? parentId,    required String ownerId,    bool isShared = false,    List<String>? sharedWithDeviceIds,  }) async {    final id = 'folder_${DateTime.now().millisecondsSinceEpoch}';    final folder = VaultFolder(      id: id,      name: name,      parentId: parentId,      createdAt: DateTime.now(),      isShared: isShared,      sharedWithDeviceIds: sharedWithDeviceIds ?? [],      ownerId: ownerId,    );    await _foldersBox?.put(id, jsonEncode(folder.toJson()));    final folderPath = Directory('${_vaultDir.path}/$id');    await folderPath.create(recursive: true);    return folder;  }  Future<void> renameFolder(String folderId, String newName) async {    final json = _foldersBox?.get(folderId);    if (json == null) return;    final folder = VaultFolder.fromJson(jsonDecode(json));    final updated = VaultFolder(      id: folder.id,      name: newName,      parentId: folder.parentId,      createdAt: folder.createdAt,      sharedWithDeviceIds: folder.sharedWithDeviceIds,      isShared: folder.isShared,      ownerId: folder.ownerId,    );    await _foldersBox?.put(folderId, jsonEncode(updated.toJson()));  }  Future<void> moveFolder(String folderId, String? newParentId) async {    final json = _foldersBox?.get(folderId);    if (json == null) return;    final folder = VaultFolder.fromJson(jsonDecode(json));    final updated = VaultFolder(      id: folder.id,      name: folder.name,      parentId: newParentId,      createdAt: folder.createdAt,      sharedWithDeviceIds: folder.sharedWithDeviceIds,      isShared: folder.isShared,      ownerId: folder.ownerId,    );    await _foldersBox?.put(folderId, jsonEncode(updated.toJson()));  }  Future<void> deleteFolder(String folderId) async {    final children = getFolders(parentId: folderId);    for (final child in children) {      await deleteFolder(child.id);    }    final files = getFiles(folderId: folderId);    for (final file in files) {      await deleteFile(file.id);    }    await _foldersBox?.delete(folderId);    final folderPath = Directory('${_vaultDir.path}/$folderId');    if (await folderPath.exists()) {      await folderPath.delete(recursive: true);    }  }  List<VaultFile> getFiles(      {String? folderId,      String? searchQuery,      FileType? type,      List<String>? tags}) {    final files = <VaultFile>[];    for (final key in _filesBox?.keys ?? []) {      final json = _filesBox?.get(key);      if (json == null) continue;      try {        final file = VaultFile.fromJson(jsonDecode(json));        if (folderId != null && file.folderId != folderId) continue;        if (type != null && file.type != type) continue;        if (tags != null && tags.isNotEmpty) {          if (!tags.any((tag) => file.tags.contains(tag))) continue;        }        if (searchQuery != null && searchQuery.isNotEmpty) {          final query = searchQuery.toLowerCase();          if (!file.name.toLowerCase().contains(query)) continue;          if (!file.tags.any((t) => t.toLowerCase().contains(query))) continue;        }        files.add(file);      } catch (_) {}    }    files.sort((a, b) => b.modifiedAt.compareTo(a.modifiedAt));    return files;  }  List<VaultFolder> getFolders({String? parentId}) {    final folders = <VaultFolder>[];    for (final key in _foldersBox?.keys ?? []) {      final json = _foldersBox?.get(key);      if (json == null) continue;      try {        final folder = VaultFolder.fromJson(jsonDecode(json));        if (parentId == null && folder.parentId == null) {          folders.add(folder);        } else if (parentId != null && folder.parentId == parentId) {          folders.add(folder);        }      } catch (_) {}    }    folders.sort((a, b) => a.name.compareTo(b.name));    return folders;  }  Future<void> renameFile(String fileId, String newName) async {    final json = _filesBox?.get(fileId);    if (json == null) return;    final file = VaultFile.fromJson(jsonDecode(json));    final updated = file.copyWith(name: newName, modifiedAt: DateTime.now());    await _filesBox?.put(fileId, jsonEncode(updated.toJson()));  }  Future<void> moveFile(String fileId, String newFolderId) async {    final json = _filesBox?.get(fileId);    if (json == null) return;    final file = VaultFile.fromJson(jsonDecode(json));    final updated =        file.copyWith(folderId: newFolderId, modifiedAt: DateTime.now());    await _filesBox?.put(fileId, jsonEncode(updated.toJson()));  }  Future<void> deleteFile(String fileId) async {    final json = _filesBox?.get(fileId);    if (json == null) return;    final file = VaultFile.fromJson(jsonDecode(json));    await _binBox?.put(fileId, json);    await _filesBox?.delete(fileId);  }  Future<void> restoreFile(String fileId) async {    final json = _binBox?.get(fileId);    if (json == null) return;    await _filesBox?.put(fileId, json);    await _binBox?.delete(fileId);  }  Future<void> permanentlyDeleteFile(String fileId) async {    final json = _binBox?.get(fileId);    if (json != null) {      final file = VaultFile.fromJson(jsonDecode(json));      final localFile = File(file.path);      if (await localFile.exists()) {        await localFile.delete();      }    }    await _binBox?.delete(fileId);    final versionKeys = _versionsBox?.keys            .where((k) => k.toString().startsWith(fileId))            .toList() ??        [];    for (final key in versionKeys) {      final vJson = _versionsBox?.get(key);      if (vJson != null) {        final version = FileVersion.fromJson(jsonDecode(vJson));        final vFile = File(version.path);        if (await vFile.exists()) {          await vFile.delete();        }      }      await _versionsBox?.delete(key);    }  }  List<VaultFile> getDeletedFiles() {    final files = <VaultFile>[];    for (final key in _binBox?.keys ?? []) {      final json = _binBox?.get(key);      if (json == null) continue;      try {        files.add(VaultFile.fromJson(jsonDecode(json)));      } catch (_) {}    }    return files;  }  Future<void> emptyBin() async {    final keys = _binBox?.keys.toList() ?? [];    for (final key in keys) {      await permanentlyDeleteFile(key.toString());    }  }  Future<void> addTag(String fileId, String tag) async {    final json = _filesBox?.get(fileId);    if (json == null) return;    final file = VaultFile.fromJson(jsonDecode(json));    if (file.tags.contains(tag)) return;    final updated = file.copyWith(tags: [...file.tags, tag]);    await _filesBox?.put(fileId, jsonEncode(updated.toJson()));  }  Future<void> removeTag(String fileId, String tag) async {    final json = _filesBox?.get(fileId);    if (json == null) return;    final file = VaultFile.fromJson(jsonDecode(json));    final updated =        file.copyWith(tags: file.tags.where((t) => t != tag).toList());    await _filesBox?.put(fileId, jsonEncode(updated.toJson()));  }  List<String> getAllTags() {    final tags = <String>{};    for (final key in _filesBox?.keys ?? []) {      final json = _filesBox?.get(key);      if (json == null) continue;      try {        final file = VaultFile.fromJson(jsonDecode(json));        tags.addAll(file.tags);      } catch (_) {}    }    return tags.toList()..sort();  }  Future<void> saveVersion(String fileId) async {    final json = _filesBox?.get(fileId);    if (json == null) return;    final file = VaultFile.fromJson(jsonDecode(json));    final localFile = File(file.path);    if (!await localFile.exists()) return;    final bytes = await localFile.readAsBytes();    final versionId = '${fileId}_v${file.version}';    final versionPath = '${_versionsDir.path}/$versionId';    await File(versionPath).writeAsBytes(bytes);    final version = FileVersion(      id: versionId,      fileId: fileId,      path: versionPath,      versionNumber: file.version,      createdAt: DateTime.now(),      checksum: _computeChecksum(bytes),    );    await _versionsBox?.put(versionId, jsonEncode(version.toJson()));    final updated = file.copyWith(version: file.version + 1);    await _filesBox?.put(fileId, jsonEncode(updated.toJson()));  }  List<FileVersion> getVersions(String fileId) {    final versions = <FileVersion>[];    for (final key in _versionsBox?.keys ?? []) {      final json = _versionsBox?.get(key);      if (json == null) continue;      try {        final version = FileVersion.fromJson(jsonDecode(json));        if (version.fileId == fileId) {          versions.add(version);        }      } catch (_) {}    }    versions.sort((a, b) => b.versionNumber.compareTo(a.versionNumber));    return versions;  }  Future<void> rollbackVersion(String fileId, int versionNumber) async {    final versionId = '${fileId}_v$versionNumber';    final json = _versionsBox?.get(versionId);    if (json == null) return;    final version = FileVersion.fromJson(jsonDecode(json));    final versionFile = File(version.path);    if (!await versionFile.exists()) return;    final fileJson = _filesBox?.get(fileId);    if (fileJson == null) return;    final currentFile = VaultFile.fromJson(jsonDecode(fileJson));    final currentLocalFile = File(currentFile.path);    await saveVersion(fileId);    final versionBytes = await versionFile.readAsBytes();    await currentLocalFile.writeAsBytes(versionBytes);  }  Map<String, int> getStorageUsage() {    final usage = <String, int>{      'image': 0,      'video': 0,      'audio': 0,      'document': 0,      'pdf': 0,      'other': 0,    };    for (final key in _filesBox?.keys ?? []) {      final json = _filesBox?.get(key);      if (json == null) continue;      try {        final file = VaultFile.fromJson(jsonDecode(json));        final category = file.type.name;        usage[category] = (usage[category] ?? 0) + file.size;        usage['other'] = (usage['other'] ?? 0) + file.size;      } catch (_) {}    }    return usage;  }  int getTotalStorageUsed() {    int total = 0;    for (final key in _filesBox?.keys ?? []) {      final json = _filesBox?.get(key);      if (json == null) continue;      try {        final file = VaultFile.fromJson(jsonDecode(json));        total += file.size;      } catch (_) {}    }    return total;  }  List<String> searchFiles(String query) {    final results = <String>[];    final lowerQuery = query.toLowerCase();    for (final key in _filesBox?.keys ?? []) {      final json = _filesBox?.get(key);      if (json == null) continue;      try {        final file = VaultFile.fromJson(jsonDecode(json));        if (file.name.toLowerCase().contains(lowerQuery)) {          results.add(file.id);        }      } catch (_) {}    }    return results;  }  Future<void> shareFolder(String folderId, List<String> deviceIds) async {    final json = _foldersBox?.get(folderId);    if (json == null) return;    final folder = VaultFolder.fromJson(jsonDecode(json));    final updated = VaultFolder(      id: folder.id,      name: folder.name,      parentId: folder.parentId,      createdAt: folder.createdAt,      sharedWithDeviceIds: deviceIds,      isShared: true,      ownerId: folder.ownerId,    );    await _foldersBox?.put(folderId, jsonEncode(updated.toJson()));  }  List<VaultFolder> getSharedFolders() {    final folders = <VaultFolder>[];    for (final key in _foldersBox?.keys ?? []) {      final json = _foldersBox?.get(key);      if (json == null) continue;      try {        final folder = VaultFolder.fromJson(jsonDecode(json));        if (folder.isShared) {          folders.add(folder);        }      } catch (_) {}    }    return folders;  }  String formatFileSize(int bytes) {    if (bytes < 1024) return '$bytes B';    if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)} KB';    if (bytes < 1024 * 1024 * 1024)      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';    return '${(bytes / (1024 * 1024 * 1024)).toStringAsFixed(1)} GB';  }  bool canPreview(String fileName) {    final type = _getFileType(fileName);    return type == FileType.image ||        type == FileType.video ||        type == FileType.audio ||        type == FileType.document ||        type == FileType.pdf;  }}